  function money(x){return '$'+Math.round(x).toLocaleString('en-US');}
  function calc(){
    var p=parseFloat(pay.value)||0;
    n.textContent=money(p*0.50); w.textContent=money(p*0.30); s.textContent=money(p*0.20);
  }
  pay.addEventListener('input',calc); pay.addEventListener('change',calc); calc();
})();
</script>
